        "intro": "Эфирные масла некоторых растений содержат гормоноподобные вещества (фитогормоны или прогормоны), способные без побочных эффектов и вмешательства в работу организма мягко и незаметно отрегулировать (текст в источнике обрывается). Если вы хотите получить быстрый результат по оздоровлению, вы можете дополнительно к работе с травами применять эфирные масла различным образом:",
